pub const ComputerAction = union(enum) {
    click_param: ClickParam,
    double_click_action: DoubleClickAction,
    drag_param: DragParam,
    key_press_action: KeyPressAction,
    move_param: MoveParam,
    screenshot_param: ScreenshotParam,
    scroll_param: ScrollParam,
    type_param: TypeParam,
    wait_param: WaitParam,

    fn parseUnionVariantFromValue(comptime T: type, allocator: std.mem.Allocator, source: std.json.Value, options: std.json.ParseOptions) !T {
        const encoded = try std.json.Stringify.valueAlloc(allocator, source, .{});
        defer allocator.free(encoded);
        return std.json.parseFromSliceLeaky(T, allocator, encoded, options) catch |err| switch (err) {
            error.OutOfMemory => return error.OutOfMemory,
            else => return error.UnexpectedToken,
        };
    }

    pub fn jsonParseFromValue(allocator: std.mem.Allocator, source: std.json.Value, options: std.json.ParseOptions) !@This() {
        if (source != .object) return error.UnexpectedToken;
        const disc_val = source.object.get("type") orelse return error.MissingField;
        const disc_str = switch (disc_val) {
            .string => |s| s,
            else => return error.UnexpectedToken,
        };
        if (std.mem.eql(u8, disc_str, "ClickParam")) {
            return .{ .click_param = try parseUnionVariantFromValue(ClickParam, allocator, source, options) };
        }
        if (std.mem.eql(u8, disc_str, "DoubleClickAction")) {
            return .{ .double_click_action = try parseUnionVariantFromValue(DoubleClickAction, allocator, source, options) };
        }
        if (std.mem.eql(u8, disc_str, "DragParam")) {
            return .{ .drag_param = try parseUnionVariantFromValue(DragParam, allocator, source, options) };
        }
        if (std.mem.eql(u8, disc_str, "KeyPressAction")) {
            return .{ .key_press_action = try parseUnionVariantFromValue(KeyPressAction, allocator, source, options) };
        }
        if (std.mem.eql(u8, disc_str, "MoveParam")) {
            return .{ .move_param = try parseUnionVariantFromValue(MoveParam, allocator, source, options) };
        }
        if (std.mem.eql(u8, disc_str, "ScreenshotParam")) {
            return .{ .screenshot_param = try parseUnionVariantFromValue(ScreenshotParam, allocator, source, options) };
        }
        if (std.mem.eql(u8, disc_str, "ScrollParam")) {
            return .{ .scroll_param = try parseUnionVariantFromValue(ScrollParam, allocator, source, options) };
        }
        if (std.mem.eql(u8, disc_str, "TypeParam")) {
            return .{ .type_param = try parseUnionVariantFromValue(TypeParam, allocator, source, options) };
        }
        if (std.mem.eql(u8, disc_str, "WaitParam")) {
            return .{ .wait_param = try parseUnionVariantFromValue(WaitParam, allocator, source, options) };
        }
        return error.UnexpectedToken;
    }

    pub fn jsonParse(allocator: std.mem.Allocator, source: anytype, options: std.json.ParseOptions) !@This() {
        const value = try std.json.Value.jsonParse(allocator, source, options);
        return try jsonParseFromValue(allocator, value, options);
    }

    pub fn jsonStringify(self: @This(), jw: anytype) !void {
        switch (self) {
            .click_param => |v| try jw.write(v),
            .double_click_action => |v| try jw.write(v),
            .drag_param => |v| try jw.write(v),
            .key_press_action => |v| try jw.write(v),
            .move_param => |v| try jw.write(v),
            .screenshot_param => |v| try jw.write(v),
            .scroll_param => |v| try jw.write(v),
            .type_param => |v| try jw.write(v),
            .wait_param => |v| try jw.write(v),
        }
    }
};

