pub const InputContent = union(enum) {
    input_text_content: InputTextContent,
    input_image_content: InputImageContent,
    input_file_content: InputFileContent,

    fn parseUnionVariantFromValue(comptime T: type, allocator: std.mem.Allocator, source: std.json.Value, options: std.json.ParseOptions) !T {
        const encoded = try std.json.Stringify.valueAlloc(allocator, source, .{});
        defer allocator.free(encoded);
        return std.json.parseFromSliceLeaky(T, allocator, encoded, options) catch |err| switch (err) {
            error.OutOfMemory => return error.OutOfMemory,
            else => return error.UnexpectedToken,
        };
    }

    pub fn jsonParseFromValue(allocator: std.mem.Allocator, source: std.json.Value, options: std.json.ParseOptions) !@This() {
        if (source != .object) return error.UnexpectedToken;
        const disc_val = source.object.get("type") orelse return error.MissingField;
        const disc_str = switch (disc_val) {
            .string => |s| s,
            else => return error.UnexpectedToken,
        };
        if (std.mem.eql(u8, disc_str, "InputTextContent")) {
            return .{ .input_text_content = try parseUnionVariantFromValue(InputTextContent, allocator, source, options) };
        }
        if (std.mem.eql(u8, disc_str, "InputImageContent")) {
            return .{ .input_image_content = try parseUnionVariantFromValue(InputImageContent, allocator, source, options) };
        }
        if (std.mem.eql(u8, disc_str, "InputFileContent")) {
            return .{ .input_file_content = try parseUnionVariantFromValue(InputFileContent, allocator, source, options) };
        }
        return error.UnexpectedToken;
    }

    pub fn jsonParse(allocator: std.mem.Allocator, source: anytype, options: std.json.ParseOptions) !@This() {
        const value = try std.json.Value.jsonParse(allocator, source, options);
        return try jsonParseFromValue(allocator, value, options);
    }

    pub fn jsonStringify(self: @This(), jw: anytype) !void {
        switch (self) {
            .input_text_content => |v| try jw.write(v),
            .input_image_content => |v| try jw.write(v),
            .input_file_content => |v| try jw.write(v),
        }
    }
};

